  function detectGlobalAirportFromText(text = '', hintAirport = 'JFK') {
    const raw = String(text || '');
    if (!raw.trim()) return AIRPORT_METADATA[hintAirport] ? hintAirport : 'JFK';

    // 1. Curated unambiguous airport & metro patterns
    for (const entry of CURATED_ALIASES) {
      if (entry.re.test(raw) && AIRPORT_METADATA[entry.code]) return entry.code;
    }

    // 2. Parenthesized 3-letter IATA code anywhere on receipt: e.g. "(YYZ)", "(AUS)", "(LHR)"
    const parenMatches = raw.matchAll(/\(([A-Z]{3})\)/g);
    for (const m of parenMatches) {
      const code = m[1].toUpperCase();
      if (!PAREN_IGNORE.has(code) && AIRPORT_METADATA[code]) return code;
    }

    const headerLines = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).slice(0, 8);
    const headerBlock = headerLines.join('\n');

    // 3. Explicit "<IATA> AIRPORT / INTL / TERMINAL" or "AIRPORT - <IATA>" in header lines (covers all 5,217 airports!)
    const beforeCtx = headerBlock.matchAll(/\b([A-Z]{3})\s+(?:INT['’]?L|INTERNATIONAL|AIRPORT|AEROPUERTO|A[EÉ]ROPORT|TERMINAL|TERM\b)/gi);
    for (const m of beforeCtx) {
      const code = m[1].toUpperCase();
      if (!CODE_STOPWORDS.has(code) && AIRPORT_METADATA[code]) return code;
    }
    const afterCtx = headerBlock.matchAll(/(?:AIRPORT|INT['’]?L|INTERNATIONAL|AEROPUERTO|A[EÉ]ROPORT)\s*[-–—:/#(]+\s*([A-Z]{3})\b/gi);
    for (const m of afterCtx) {
      const code = m[1].toUpperCase();
      if (!CODE_STOPWORDS.has(code) && AIRPORT_METADATA[code]) return code;
    }

    // 4. Safe major hub code token in top 4 header lines (e.g. "HUDSON NONSTOP YYZ", "STARBUCKS #7140 BOS")
    const topHeaderTokens = headerLines.slice(0, 4).join(' ').match(/\b[A-Z]{3}\b/g) || [];
    for (const tok of topHeaderTokens) {
      if (SAFE_HEADER_HUBS.has(tok) && AIRPORT_METADATA[tok]) return tok;
    }

    // 5. Header line explicitly mentions AIRPORT/INTL/AEROPUERTO: match city name in ranked global priority order
    const airHeaderLine = headerLines.find((l) => /\b(?:AIRPORT|INT['’]?L|INTERNATIONAL|AEROPUERTO|A[EÉ]ROPORT)\b/i.test(l));
    if (airHeaderLine) {
      const upperLine = airHeaderLine.toUpperCase();
      for (let i = 0; i < WORLD_AIRPORTS_LIST.length; i++) {
        const a = WORLD_AIRPORTS_LIST[i];
        const primaryCity = a.city.split(',')[0].trim().toUpperCase();
        if (primaryCity.length >= 4 && upperLine.includes(primaryCity)) {
          return a.code;
        }
      }
    }

    return AIRPORT_METADATA[hintAirport] ? hintAirport : 'JFK';
  }

